import type {Context} from "glyph-engine";
import type {Hole} from "../scene/background";
import type {Line} from "../terminal/lines";
import {shellPage} from "../shell/shell";
import {tabs} from "../terminal/pages";
import {strings} from "../terminal/strings";
import {c} from "../theme";
import {put, type Frame} from "./frame";
import {ROOMY_COLS} from "./layout";
import type {App} from "./state";

const FRAME_WIDTH = 5; // borders, padding, scrollbar
const BLINK_MS = 500;
const REVEAL_ROWS_PER_FRAME = 3;

function linesFor(app: App, width: number) {
    const key = `${app.lang}:${app.tab}:${width}:${app.shell.revision}`;
    if (key !== app.pageKey) {
        app.pageKey = key;
        app.pageLines = shellPage(tabs[app.tab]!, app.shell, width, app.lang);
    }
    return app.pageLines;
}

function drawLine(frame: Frame, app: App, line: Line, x: number, y: number, maxX: number) {
    const {mouseX, mouseY} = frame;
    let at = x;
    for (const span of line) {
        const start = at;
        const hover = !!span.url && app.hover && mouseY === y && mouseX >= start && mouseX < start + [...span.text].length;
        at = put(frame, span.text, at, y, {
            color: hover ? c.crust : span.color,
            backgroundColor: hover ? c.link : c.base,
            fontWeight: span.bold ? "bold" : "normal",
        }, maxX);
        if (span.url) app.hits.push({x0: start, x1: at, y, action: {kind: "url", url: span.url}});
    }
    return at;
}

function drawScrollbar(frame: Frame, app: App, x: number, y: number, height: number, lineCount: number) {
    const thumb = Math.max(1, Math.round((height * height) / lineCount));
    const top = Math.round((app.scroll / app.maxScroll) * (height - thumb));
    for (let i = 0; i < height; i++) {
        const on = i >= top && i < top + thumb;
        put(frame, on ? "┃" : "│", x, y + i, {color: on ? c.accent : c.surface});
    }
}

function drawFooter(frame: Frame, app: App, win: Hole) {
    const text = strings[app.lang];
    const hint = frame.cols < ROOMY_COLS ? text.swipe : app.shell.active ? text.exit : ` 1-${tabs.length} ${text.keys}${app.hover ? text.shell : ""}`;
    const percent = app.maxScroll ? ` ${Math.round((app.scroll / app.maxScroll) * 100)}% ` : "";
    const bottom = win.y + win.h - 1;
    put(frame, hint, win.x + 2, bottom, {color: c.dim}, win.x + win.w - 2);
    put(frame, percent, win.x + win.w - 2 - percent.length, bottom, {color: c.dim});
}

export function drawPage(frame: Frame, app: App, win: Hole, context: Context) {
    const x = win.x + 2;
    const y = win.y + 1;
    const width = win.w - FRAME_WIDTH;
    const height = win.h - 2;
    const lines = linesFor(app, width);
    app.pageWidth = width;
    app.viewRows = height;
    app.maxScroll = Math.max(0, lines.length - height);
    app.scroll = Math.min(app.scroll, app.maxScroll);

    const revealed = app.reduced || app.tab !== 0 ? Infinity : context.frame * REVEAL_ROWS_PER_FRAME;
    for (let row = 0; row < height; row++) {
        const index = row + app.scroll;
        const line = lines[index];
        if (!line || index > revealed) break;
        const end = drawLine(frame, app, line, x, y + row, x + width);
        const last = index === lines.length - 1;
        if (last && Math.floor(context.time / BLINK_MS) % 2 === 0) put(frame, "█", end, y + row, {color: c.text});
        if (last && app.hover && !app.shell.active) app.hits.push({x0: x, x1: x + width, y: y + row, action: {kind: "shell"}});
    }

    if (app.maxScroll > 0) drawScrollbar(frame, app, win.x + win.w - 2, y, height, lines.length);
    drawFooter(frame, app, win);
}
