import {FLAKE} from "../theme";
import type {View} from "./camera";
import {CELL, plot, type Overlay} from "./overlay";
import {mulberry32} from "./random";
import {SNOW_END, SNOW_START, yearTime} from "./timeline";

const CHARS = ["\u{f0717}", "\u{f2dc}", "\u{f0f2a}", "."];
const MAX_FLAKES = 600;
const CELLS_PER_FLAKE = 60;
const SEED = 1337;

const FLAKES = (() => {
    const random = mulberry32(SEED);
    return Array.from({length: MAX_FLAKES}, () => ({
        x: random(), land: random(), offset: random(), drift: random() * Math.PI * 2,
        period: 5000 + random() * 4000, z: random() * 2 - 1, char: CHARS[Math.floor(random() * CHARS.length)]!,
    }));
})();

// A flake only starts if it is snowing at that moment, then always finishes its fall.
export function drawSnow(overlay: Overlay, {cy, radius, time}: View) {
    const {cols, rows} = overlay;
    const count = Math.min(MAX_FLAKES, Math.ceil((cols * rows) / CELLS_PER_FLAKE));
    const ground = cy + radius;
    for (let i = 0; i < count; i++) {
        const flake = FLAKES[i]!;
        const progress = (time / flake.period + flake.offset) % 1;
        const started = yearTime(time - progress * flake.period);
        if (started < SNOW_START || started >= SNOW_END) continue;
        const x = flake.x * cols + Math.sin(progress * 6 + flake.drift) * 2;
        plot(overlay, x, progress * (ground + flake.land * (rows - ground)), flake.z, flake.char, FLAKE, CELL.snow);
    }
}
