import type {Buffer, Context, Coord, Cursor, Program} from "glyph-engine";
import {shade} from "../scene/background";
import {createOverlay} from "../scene/overlay";
import {rasterize} from "../scene/rasterize";
import {FROZEN_TIME, seasonAt, START_TIME, viewYaw} from "../scene/timeline";
import {SCALE} from "../scene/tree";
import {tabs} from "../terminal/pages";
import {layout} from "./layout";
import {drawPage} from "./page-view";
import {hitAt, type App} from "./state";
import {drawTabBar} from "./tab-bar";
import {drawWindow} from "./window";

function updateScene(app: App, context: Context, cursor: Cursor) {
    const {cols, rows} = context;
    const aspect = context.metrics.aspect;
    const {win, tree, horizon} = layout(cols, rows, aspect, tabs[app.tab]!.scene);
    const time = app.reduced ? FROZEN_TIME : context.time + START_TIME;
    if (app.hover) app.tiltY = (cursor.x / cols - 0.5) * 1.2;
    if (app.overlay.depth.length !== cols * rows) app.overlay = createOverlay(cols, rows);

    const {brown, snow} = seasonAt(time);
    const yaw = viewYaw(app.reduced ? FROZEN_TIME : Date.now(), app.tiltY);
    const {scene} = app;
    scene.hole = win;
    scene.time = time;
    scene.horizon = horizon;
    scene.yaw = yaw;
    scene.cx = tree.cx;
    scene.base = tree.cy + tree.radius;
    scene.shadow = tree.radius * SCALE;
    scene.brown = brown;
    scene.snow = snow;
    rasterize({aspect, ...tree, time, yaw, horizon}, app.overlay, app.tree);
}

function drawInterface(app: App, context: Context, cursor: Cursor, buffer: Buffer) {
    const {cols, rows} = context;
    const mouseX = Math.floor(cursor.x), mouseY = Math.floor(cursor.y);
    const frame = {buffer, cols, rows, mouseX, mouseY};
    app.cellWidth = context.metrics.cellWidth;
    app.lineHeight = context.metrics.lineHeight;
    // Hits from the frame on screen, since that is what the cursor is over.
    (context.settings.element as HTMLElement).style.cursor = hitAt(app, mouseX, mouseY) && app.hover ? "pointer" : "default";
    app.hits.length = 0;

    drawTabBar(frame, app);
    const tab = tabs[app.tab]!;
    if (tab.scene) {
        app.maxScroll = 0;
        return;
    }
    const {win} = layout(cols, rows, context.metrics.aspect);
    drawWindow(frame, app, win, tab);
    drawPage(frame, app, win, context);
}

// The engine requires callbacks, so the closure is what passes the app down.
export const createProgram = (app: App): Program => ({
    pre: (context, cursor) => updateScene(app, context, cursor),
    main: (coord: Coord, context) => shade(coord, context, app.scene, app.overlay),
    post: (context, cursor, buffer) => drawInterface(app, context, cursor, buffer),
});
