import type {Line} from "../terminal/lines";
import {page, promptLine, type Tab} from "../terminal/pages";
import {c} from "../theme";
import type {Lang} from "../cv/data";
import {commandNames, createFilesystem, execute, type Env} from "./commands";
import {displayPath, expandHome, lookup, plainLine, resolvePath, type DirNode} from "./filesystem";

// tries and failure only: what was typed at a password prompt is never kept anywhere.
type PasswordPrompt = { prompt: string; tries: number; failure: string };

export type Shell = {
    root: DirNode;
    active: boolean;
    cwd: string;
    input: string;
    transcript: Line[];
    cleared: boolean; // "clear" also removes the tab's page
    commandHistory: string[];
    historyIndex: number;
    password: PasswordPrompt | null;
    openTab: number | null; // set by a command, carried out by the input layer
    revision: number; // bumped on every change, so the page is rebuilt only then
};

export const createShell = (dir: string): Shell => ({
    root: createFilesystem(),
    active: false,
    cwd: expandHome(dir),
    input: "",
    transcript: [],
    cleared: false,
    commandHistory: [],
    historyIndex: 0,
    password: null,
    openTab: null,
    revision: 0,
});

export function closeShell(shell: Shell) {
    shell.active = false;
    shell.revision++;
}

export function clearScreen(shell: Shell) {
    shell.transcript = [];
    shell.cleared = true;
    shell.revision++;
}

export function resetShell(shell: Shell, dir: string) {
    shell.active = false;
    shell.cwd = expandHome(dir);
    shell.input = "";
    shell.transcript = [];
    shell.cleared = false;
    shell.password = null;
    shell.revision++;
}

const commandEcho = (text: string): Line => [{text: "$ ", color: c.red, bold: true}, ...(text ? [{text, color: c.text}] : [])];
const prompt = (shell: Shell) => promptLine(displayPath(shell.cwd));

function answerPassword(shell: Shell) {
    const asked = shell.password!;
    shell.transcript.push(plainLine(asked.prompt));
    if (asked.tries > 1) {
        shell.password = {...asked, tries: asked.tries - 1};
        shell.transcript.push(plainLine("Sorry, try again."));
        return;
    }
    shell.password = null;
    shell.transcript.push(plainLine(asked.failure));
}

export function submit(shell: Shell, env: Env) {
    shell.revision++;
    if (shell.password) return answerPassword(shell);
    const line = shell.input.trim();
    shell.transcript.push(prompt(shell), commandEcho(shell.input));
    shell.input = "";
    if (!line) return;
    shell.commandHistory.push(line);
    shell.historyIndex = shell.commandHistory.length;
    const output = execute(line, shell, env);
    shell.transcript.push(...output);
}

export function typeText(shell: Shell, text: string) {
    if (shell.password) return;
    shell.input += text;
    shell.revision++;
}

export function erase(shell: Shell) {
    shell.input = [...shell.input].slice(0, -1).join("");
    shell.revision++;
}

export function interrupt(shell: Shell) {
    if (!shell.password) shell.transcript.push(prompt(shell), commandEcho(`${shell.input}^C`));
    else shell.transcript.push(plainLine(shell.password.prompt));
    shell.password = null;
    shell.input = "";
    shell.revision++;
}

export function stepHistory(shell: Shell, step: number) {
    const {commandHistory} = shell;
    shell.historyIndex = Math.max(0, Math.min(commandHistory.length, shell.historyIndex + step));
    shell.input = commandHistory[shell.historyIndex] ?? "";
    shell.revision++;
}

const sharedPrefix = (names: string[]) => names.reduce((a, b) => {
    let i = 0;
    while (i < a.length && a[i] === b[i]) i++;
    return a.slice(0, i);
});

export function complete(shell: Shell) {
    const start = shell.input.lastIndexOf(" ") + 1;
    const word = shell.input.slice(start);
    const slash = word.lastIndexOf("/") + 1;
    const folder = word.slice(0, slash);
    const stem = word.slice(slash);
    const node = lookup(shell.root, resolvePath(shell.cwd, folder || "."));
    const entries = start === 0 ? commandNames : node?.kind === "dir" && !node.locked ? Object.keys(node.entries) : [];
    const matches = entries.filter((name) => name.startsWith(stem) && (stem || !name.startsWith(".")));
    if (!matches.length) return;
    let completed = sharedPrefix(matches);
    if (matches.length === 1 && start > 0 && node?.kind === "dir") completed += node.entries[completed]?.kind === "dir" ? "/" : " ";
    else if (matches.length === 1) completed += " ";
    shell.input = shell.input.slice(0, start) + folder + completed;
    shell.revision++;
}

// The tab's page with the session after it, ending on the live prompt the renderer blinks.
export function shellPage(tab: Tab, shell: Shell, width: number, lang: Lang): Line[] {
    const base = shell.cleared ? [] : page(tab, width, lang).slice(0, -2);
    const live = shell.password ? [plainLine(shell.password.prompt)] : [prompt(shell), commandEcho(shell.input)];
    return [...base, ...shell.transcript, ...live];
}
