import {data, type Lang} from "../cv/data";
import {c} from "../theme";
import {blockLines, type Line} from "./lines";
import {LOGO, LOGO_WIDTH, TRUNK_START} from "./logo";
import {strings} from "./strings";

// Sections sit in the same order in every language; tests/terminal.test.ts enforces it.
const SECTION = {summary: 0, skills: 1, experience: 2, projects: 3, publications: 4, education: 5, languages: 6, notes: 7};

function renderSection(index: number, width: number, lang: Lang): Line[] {
    const section = data[lang].sections[index]!;
    const lines: Line[] = [[{text: `## ${section.title.toLowerCase()}`, color: c.accent, bold: true}], []];
    section.blocks.forEach((block, i) => {
        if (i > 0 && block.kind === "role") lines.push([]);
        lines.push(...blockLines(block, width));
    });
    lines.push([]);
    return lines;
}

const BRANCHES: [string, string][] = [
    [c.yellow, "\uf007  "], [c.yellow, "│ ├"], [c.yellow, "│ ├"], [c.yellow, "│ └"],
    [c.accent, "\uf0b1  "], [c.accent, "│ ├"], [c.accent, "│ └"],
    [c.green, "\uf121  "], [c.green, "│ ├"], [c.green, "│ └"],
    [c.mauve, "\uf091  "], [c.mauve, "│ ├"], [c.mauve, "│ └"],
];

const SWATCHES = [c.red, c.peach, c.yellow, c.green, c.teal, c.blue, c.mauve];

function fetchLines(width: number, lang: Lang): Line[] {
    const tree: Line[] = [
        [{text: "nicolas", color: c.accent, bold: true}, {text: "@", color: c.text}, {text: "medis", color: c.accent, bold: true}],
        [{text: "─".repeat(13), color: c.dim}],
        [{text: "MedisOS 1.0 (Ąžuolas)", color: c.green, bold: true}],
        ...strings[lang].tree.map(([key, value], i): Line => {
            const [color, branch] = BRANCHES[i]!;
            return [
                {text: `${branch} ${key.padEnd(8)}`, color, bold: key === key.toUpperCase()},
                {text: value, color: c.text},
            ];
        }),
        [],
        [{text: SWATCHES.map(() => "███").join(""), color: c.text}],
    ];
    tree[tree.length - 1] = SWATCHES.map((color) => ({text: "███", color}));

    const fits = width >= LOGO_WIDTH + 38;
    const rows: Line[] = fits
        ? Array.from({length: Math.max(LOGO.length, tree.length)}, (_, i) => [{text: (LOGO[i] ?? "").padEnd(LOGO_WIDTH), color: i < TRUNK_START ? c.mauve : c.sub, bold: true}, ...(tree[i] ?? [])])
        : tree;
    const about = data[lang].sections[SECTION.summary]!.blocks.flatMap((b) => blockLines(b, width));
    return [...rows, [], ...about, []];
}

function contactLines(width: number, lang: Lang): Line[] {
    const {header} = data[lang];
    const linkRows = header.filter((b) => b.links.length).map((b): Line => {
        const label = b.text;
        const url = b.links[0]!.url;
        const shown = url.replace(/^mailto:|^https:\/\/(www\.)?/, "");
        return [{text: `\uf0c1 ${shown === label ? label : `${label.padEnd(10)} ${shown}`}`, color: c.link, url}];
    });
    const place = header.filter((b) => b.kind === "text" && !b.links.length && !b.text.startsWith("NICOLAS"));
    return [
        [{text: `## ${strings[lang].contact}`, color: c.accent, bold: true}],
        [],
        ...place.flatMap((b) => blockLines(b, width)),
        [],
        ...linkRows,
        [],
    ];
}

export type Tab = {
    names: Record<Lang, [name: string, short: string]>;
    icon: string; dir: string; cmd: string;
    body: (width: number, lang: Lang) => Line[];
    scene?: boolean; // no window, the whole screen is the animation
};

export const tabs: Tab[] = [
    {names: {en: ["whoami", "who"], pt: ["whoami", "quem"], lt: ["whoami", "kas"]}, icon: "\uf1bb", dir: "~", cmd: "fastfetch", body: fetchLines},
    {names: {en: ["roles", "work"], pt: ["carreira", "exp"], lt: ["karjera", "darb"]}, icon: "\uf0b1", dir: "~/roles", cmd: "bat roles.md", body: (w, l) => renderSection(SECTION.experience, w, l)},
    {names: {en: ["projects", "proj"], pt: ["projetos", "proj"], lt: ["projektai", "proj"]}, icon: "\uf07b", dir: "~/projects", cmd: "bat README.md", body: (w, l) => renderSection(SECTION.projects, w, l)},
    {names: {en: ["notes", "note"], pt: ["notas", "nota"], lt: ["užrašai", "užr"]}, icon: "\uf02d", dir: "~/notes", cmd: "bat *.md", body: (w, l) => renderSection(SECTION.notes, w, l)},
    {names: {en: ["skills", "tech"], pt: ["skills", "tech"], lt: ["įgūdžiai", "tech"]}, icon: "\uf121", dir: "~/.config", cmd: "bat skills.toml", body: (w, l) => renderSection(SECTION.skills, w, l)},
    {
        names: {en: ["papers", "pubs"], pt: ["artigos", "pubs"], lt: ["straipsniai", "publ"]}, icon: "\uf19d", dir: "~/papers", cmd: "bat *.md",
        body: (w, l) => [SECTION.publications, SECTION.education, SECTION.languages].flatMap((s) => renderSection(s, w, l)),
    },
    {names: {en: ["contact", "mail"], pt: ["contato", "mail"], lt: ["kontaktai", "mail"]}, icon: "\uf0e0", dir: "~/contact", cmd: "bat links.md", body: contactLines},
    {names: {en: ["medis", "tree"], pt: ["medis", "arv"], lt: ["medis", "med"]}, icon: "\uf06c", dir: "~/medis", cmd: "medis", body: () => [], scene: true},
];

// The tab's name in the URL. English in every language, so a shared link works for anyone.
export const tabSlug = (tab: Tab) => tab.names.en[0];
export const tabIndexFor = (slug: string | null) => Math.max(0, tabs.findIndex((tab) => tabSlug(tab) === slug));

// ys zsh theme prompt, then the tab's output, then a live prompt the renderer blinks.
export const promptLine = (dir: string): Line => [
    {text: "# ", color: c.accent, bold: true}, {text: "nicolas", color: c.teal},
    {text: " @ ", color: c.dim}, {text: "medis", color: c.green},
    {text: " in ", color: c.dim}, {text: dir, color: c.yellow, bold: true},
];

export function page(tab: Tab, width: number, lang: Lang): Line[] {
    const prompt = promptLine(tab.dir);
    return [
        prompt,
        [{text: "$ ", color: c.red, bold: true}, {text: tab.cmd, color: c.text}],
        [],
        ...tab.body(width, lang),
        prompt,
        [{text: "$ ", color: c.red, bold: true}],
    ];
}
