// The yearly cycle on one adult tree. Everything on screen is a pure function of time, so no
// simulation state accumulates. Winter ends bare and spring starts bare, so the loop has no seam.

export const SPRING = 30000;
const SUMMER = 15000;
const AUTUMN = 25000;
const WINTER = 12000;
export const AUTUMN_START = SPRING + SUMMER;
export const WINTER_START = AUTUMN_START + AUTUMN;
export const CYCLE = WINTER_START + WINTER;
export const SNOW_START = AUTUMN_START + AUTUMN * 0.85;
// The last flakes land in early spring, during the thaw.
export const SNOW_END = CYCLE - 4000;
const THAW = SPRING * 0.25;

// Full summer crown, shown when the visitor asks for reduced motion.
export const FROZEN_TIME = SPRING + 1;
// Visitors arrive mid-spring, with buds opening and flowers out.
export const START_TIME = SPRING * 0.4;

export const clamp01 = (n: number) => Math.max(0, Math.min(1, n));
const ease = (n: number) => n * n * (3 - 2 * n);

export const yearTime = (time: number) => time % CYCLE;

const SPIN_RADIANS_PER_MS = 0.00009;
// Takes wall-clock time, so the angle survives a reload.
export const viewYaw = (time: number, tiltY: number) => time * SPIN_RADIANS_PER_MS + tiltY;

export const autumnAt = (local: number) => clamp01((local - AUTUMN_START) / AUTUMN);

// Terrain state, 0..1. Brown and snow both fade out early in spring, so the cycle has no jump.
export function seasonAt(time: number) {
    const local = yearTime(time);
    if (local < AUTUMN_START) {
        const left = ease(1 - clamp01(local / THAW));
        return {brown: left, snow: left};
    }
    const brown = ease(clamp01((local - AUTUMN_START) / (AUTUMN * 0.8)));
    const snow = ease(clamp01((local - SNOW_START) / (WINTER_START + WINTER * 0.5 - SNOW_START)));
    return {brown, snow};
}
