import {aimCamera, type View} from "./camera";
import {drawGraves} from "./graves";
import {drawLeaves} from "./leaves";
import {lightPass} from "./lighting";
import type {Overlay} from "./overlay";
import {drawSnow} from "./snowfall";
import {autumnAt, yearTime} from "./timeline";
import {drawWood, type Tree} from "./tree";

export function rasterize(view: View, overlay: Overlay, tree: Tree) {
    overlay.depth.fill(Infinity);
    if (view.radius <= 0) return;

    const local = yearTime(view.time);
    const camera = aimCamera(view, view.yaw);

    drawGraves(overlay, view, view.yaw);
    drawWood(overlay, camera, tree);
    drawLeaves(overlay, camera, tree, local, autumnAt(local));
    drawSnow(overlay, view);
    lightPass(overlay);
}
