import type {Lang} from "../cv/data";
import type {Line} from "../terminal/lines";
import {tabs, tabSlug} from "../terminal/pages";
import {c} from "../theme";

export const HOME = "/home/nicolas";

export type FileNode = { kind: "file"; locked?: boolean; read: (width: number, lang: Lang) => Line[] };
export type DirNode = { kind: "dir"; locked?: boolean; entries: Record<string, FsNode> };
export type FsNode = FileNode | DirNode;

export const plainLine = (text: string): Line => [{text, color: c.text}];
const text = (content: string): FileNode => ({kind: "file", read: () => content.split("\n").map(plainLine)});
const dir = (entries: Record<string, FsNode> = {}, locked = false): DirNode => ({kind: "dir", entries, locked});
const tabFile = (slug: string): FileNode => {
    const tab = tabs.find((t) => tabSlug(t) === slug)!;
    return {kind: "file", read: tab.body};
};

const OS_RELEASE = `NAME="MedisOS"
VERSION="1.0 (Ąžuolas)"
ID=medis
PRETTY_NAME="MedisOS 1.0 (Ąžuolas)"`;

const PASSWD = `root:x:0:0:root:/root:/usr/bin/zsh
nicolas:x:1000:1000:Nicolas:${HOME}:/usr/bin/zsh`;

// Only published CV pages and made-up system files: this tree ships to every visitor.
export const createRoot = (commandNames: string[]): DirNode => {
    const binaries = dir(Object.fromEntries(commandNames.map((name) => [name, text(`${name}: binary file`)])));
    return dir({
        bin: binaries,
        boot: dir({vmlinuz: text("vmlinuz: binary file")}),
        dev: dir({null: text("")}),
        etc: dir({
            hostname: text("medis"),
            motd: text("Welcome to MedisOS. Everything here is read-only."),
            "os-release": text(OS_RELEASE),
            passwd: text(PASSWD),
            shadow: {...text(""), locked: true},
        }),
        home: dir({
            nicolas: dir({
                ".config": dir({"skills.toml": tabFile("skills")}),
                ".zshrc": text('export EDITOR=nvim\nalias cat=bat'),
                contact: dir({"links.md": tabFile("contact")}),
                medis: dir(),
                notes: dir({"notes.md": tabFile("notes")}),
                papers: dir({"papers.md": tabFile("papers")}),
                projects: dir({"README.md": tabFile("projects")}),
                roles: dir({"roles.md": tabFile("roles")}),
            }),
        }),
        root: dir({}, true),
        tmp: dir(),
        usr: dir({bin: binaries}),
        var: dir({log: dir()}),
    });
};

export const expandHome = (path: string) => (path === "~" || path.startsWith("~/") ? HOME + path.slice(1) : path);
export const displayPath = (path: string) => (path === HOME || path.startsWith(`${HOME}/`) ? `~${path.slice(HOME.length)}` : path);

export function resolvePath(cwd: string, path: string) {
    const expanded = expandHome(path);
    const parts: string[] = [];
    for (const part of (expanded.startsWith("/") ? expanded : `${cwd}/${expanded}`).split("/")) {
        if (part === "..") parts.pop();
        else if (part && part !== ".") parts.push(part);
    }
    return `/${parts.join("/")}`;
}

// Stops at a locked directory, so everything under it reads as denied, as it would for real.
export function lookup(root: DirNode, path: string): FsNode | undefined {
    let node: FsNode = root;
    for (const part of path.split("/").filter(Boolean)) {
        if (node.kind !== "dir") return undefined;
        if (node.locked) return node;
        const next: FsNode | undefined = node.entries[part];
        if (!next) return undefined;
        node = next;
    }
    return node;
}
