import {buffer as cells} from "glyph-engine";
import {tabs} from "../terminal/pages";
import {c} from "../theme";
import {put, type Frame} from "./frame";
import {COMPACT_TAB_COLS} from "./layout";
import type {App} from "./state";

const twoDigits = (n: number) => String(n).padStart(2, "0");

function drawClock(frame: Frame) {
    const now = new Date();
    const clock = ` ${twoDigits(now.getHours())}:${twoDigits(now.getMinutes())} `;
    put(frame, clock, frame.cols - [...clock].length, 0, {color: c.sub, backgroundColor: c.mantle});
}

// waybar-style tab row
export function drawTabBar(frame: Frame, app: App) {
    const {buffer, cols, rows, mouseX, mouseY} = frame;
    cells.setRect({char: " ", color: c.text, backgroundColor: c.mantle, fontWeight: "normal"}, 0, 0, cols, 1, buffer, cols, rows);
    const compact = cols < COMPACT_TAB_COLS;
    const slot = compact ? Math.floor(cols / tabs.length) : 0;
    let x = compact ? 0 : 1;
    for (let i = 0; i < tabs.length; i++) {
        const tab = tabs[i]!;
        const [name, short] = tab.names[app.lang];
        const label = compact ? `${tab.icon} ${short}` : ` ${i + 1}:${tab.icon} ${name} `;
        const width = compact ? slot : [...label].length;
        const active = i === app.tab;
        const hover = app.hover && mouseY === 0 && mouseX >= x && mouseX < x + width;
        cells.setRect({char: " ", backgroundColor: active ? c.accent : c.mantle}, x, 0, width, 1, buffer, cols, rows);
        put(frame, label.slice(0, width + 1), x, 0, {
            color: active ? c.crust : hover ? c.accent : c.sub,
            backgroundColor: active ? c.accent : c.mantle,
            fontWeight: active ? "bold" : "normal",
        }, x + width);
        app.hits.push({x0: x, x1: x + width, y: 0, action: {kind: "tab", index: i}});
        x += width;
    }
    if (!compact) drawClock(frame);
}
