import {semanticHtml} from "../cv/semantic-html";
import type {Lang} from "../cv/data";
import {tabs, tabSlug} from "../terminal/pages";
import {selectTab, type App, type HitAction} from "./state";

// null drops the parameter, so defaults keep the URL clean.
function setUrlParam(name: string, value: string | null) {
    const url = new URL(location.href);
    if (value === null) url.searchParams.delete(name);
    else url.searchParams.set(name, value);
    history.replaceState(null, "", url);
}

export function showTab(app: App, index: number) {
    selectTab(app, index);
    setUrlParam("tab", app.tab === 0 ? null : tabSlug(tabs[app.tab]!));
}

export function setLang(app: App, lang: Lang) {
    app.lang = lang;
    app.scroll = 0;
    document.documentElement.lang = lang;
    document.getElementById("cv")!.innerHTML = semanticHtml(lang);
    setUrlParam("lang", lang === "en" ? null : lang);
    try {
        localStorage.setItem("lang", lang);
    } catch {
        // Storage can be blocked; the choice then lasts for this page only.
    }
}

function openUrl(url: string) {
    if (url.startsWith("mailto:")) location.href = url;
    else window.open(url, "_blank", "noopener");
}

export function openShell(app: App) {
    if (!app.hover || tabs[app.tab]!.scene) return; // touch devices have no keyboard to type with
    app.shell.active = true;
    app.shell.revision++;
    app.scroll = Infinity;
}

export function runHit(app: App, action: HitAction) {
    if (action.kind === "tab") showTab(app, action.index);
    else if (action.kind === "shell") openShell(app);
    else if (action.kind === "lang") setLang(app, action.lang);
    else openUrl(action.url);
}
